// src/data/catalog.ts
function slugify(s) {
  return s.toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
function parse() {
  return Object.entries(RAW).map(([name, body]) => {
    let group;
    const entries = [];
    for (const line of body.split("\n")) {
      const t = line.trim();
      if (!t) continue;
      if (t.startsWith("## ")) {
        group = t.slice(3);
        continue;
      }
      const [id, title, d, tag] = t.split("|");
      entries.push({
        slug: `${id.toLowerCase()}-${slugify(title)}`,
        id,
        title,
        difficulty: DIFF[d],
        tag,
        category: name,
        group
      });
    }
    return { id: slugify(name), name, entries };
  });
}
function withPacks(base, problems8) {
  const cats = base.map((c) => ({ ...c, entries: [...c.entries] }));
  for (const p of problems8) {
    let cat = cats.find((c) => c.name === p.category);
    if (!cat) {
      cat = { id: slugify(p.category), name: p.category, entries: [] };
      cats.push(cat);
    }
    cat.entries.push({
      slug: `${p.id.toLowerCase()}-${slugify(p.title)}`,
      id: p.id,
      title: p.title,
      difficulty: p.difficulty,
      tag: p.tag,
      category: p.category,
      group: p.group
    });
  }
  return cats;
}
function buildCatalog(packProblems) {
  return withPacks(parse(), packProblems);
}
