// src/problems/stockAtMostK.ts
function statesFor3(k, prices) {
  const out = [];
  for (let j = 1; j <= k; j++) {
    const b = 2 * (j - 1);
    const s = b + 1;
    out.push({
      name: `buy ${j}`,
      init: -prices[0],
      step: (prev, p) => {
        const before = j === 1 ? 0 : prev[s - 2];
        const start = before - p;
        return {
          value: Math.max(prev[b], start),
          from: j === 1 ? [b] : [b, s - 2],
          moved: start > prev[b],
          desc: `Keep the stock bought for trade ${j}: ${prev[b]}. Or start trade ${j} today after ${j === 1 ? "doing nothing (profit 0)" : `finishing trade ${j - 1} (${before})`}: ${before} \u2212 ${p} = ${start}. ${start > prev[b] ? "Starting now is better." : "Keep the earlier purchase."}`
        };
      }
    });
    out.push({
      name: `sell ${j}`,
      init: 0,
      step: (prev, p) => {
        const finish = prev[b] + p;
        return {
          value: Math.max(prev[s], finish),
          from: [s, b],
          moved: finish > prev[s],
          desc: `Keep the best finished profit for ${j} trade${j === 1 ? "" : "s"}: ${prev[s]}. Or sell today the stock held for trade ${j}: ${prev[b]} + ${p} = ${finish}. ${finish > prev[s] ? "Selling now improves it." : "No improvement."}`
        };
      }
    });
  }
  return out;
}
